#if UNITY_EDITOR
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
using Object = UnityEngine.Object;

namespace VfxKit
{
    public enum VfxBlend { Additive, Alpha, Multiply }

    /// <summary>
    /// Shared helpers for effect build scripts generated by the vfx-maker skill.
    /// Each effect has its own Assets/VFX/&lt;Effect&gt;/Editor/&lt;Effect&gt;Build.cs that calls into this kit.
    /// </summary>
    public static class VfxBuildKit
    {
        public const string Version = "1.1.0";   // 1.1.0: SaveNested (each layer = its own component prefab)

        public static bool IsURP
        {
            get
            {
                var rp = GraphicsSettings.currentRenderPipeline;
                return rp != null && rp.GetType().FullName.Contains("Universal");
            }
        }

        public static void EnsureFolders(string root, params string[] subfolders)
        {
            Directory.CreateDirectory(root);
            foreach (var s in subfolders) Directory.CreateDirectory(Path.Combine(root, s));
            AssetDatabase.Refresh();
        }

        // ---------------------------------------------------------------- Textures

        /// <param name="alphaFromGray">Use brightness as alpha (black-background textures used with alpha blend).</param>
        public static Texture2D ImportTexture(string path, int maxSize = 512, bool alphaFromGray = false, bool clamp = true)
        {
            var importer = AssetImporter.GetAtPath(path) as TextureImporter;
            if (importer == null) throw new FileNotFoundException("Texture not found or not imported: " + path);
            importer.textureType = TextureImporterType.Default;
            importer.alphaSource = alphaFromGray ? TextureImporterAlphaSource.FromGrayScale : TextureImporterAlphaSource.FromInput;
            importer.alphaIsTransparency = true;
            importer.sRGBTexture = true;
            importer.mipmapEnabled = true;
            importer.wrapMode = clamp ? TextureWrapMode.Clamp : TextureWrapMode.Repeat;
            importer.filterMode = FilterMode.Bilinear;
            importer.maxTextureSize = maxSize;
            importer.textureCompression = TextureImporterCompression.Compressed;
            importer.isReadable = false;
            importer.SaveAndReimport();
            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }

        // ---------------------------------------------------------------- Materials

        public static string DefaultShader(VfxBlend blend)
        {
            if (IsURP) return "Universal Render Pipeline/Particles/Unlit";
            switch (blend)
            {
                case VfxBlend.Additive: return "Mobile/Particles/Additive";
                case VfxBlend.Multiply: return "Mobile/Particles/Multiply";
                default: return "Mobile/Particles/Alpha Blended";
            }
        }

        /// <summary>Creates or updates a material. Picks a stock particle shader for the active pipeline unless shaderName is given.</summary>
        public static Material Material(string path, VfxBlend blend, Texture texture, string shaderName = null)
        {
            string name = shaderName ?? DefaultShader(blend);
            Shader shader = Shader.Find(name);
            if (shader == null || !shader.isSupported) throw new InvalidOperationException("Shader unavailable: " + name);

            var mat = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (mat == null) { mat = new Material(shader); AssetDatabase.CreateAsset(mat, path); }
            mat.shader = shader;
            if (texture != null)
            {
                if (mat.HasProperty("_BaseMap")) mat.SetTexture("_BaseMap", texture);
                if (mat.HasProperty("_MainTex")) mat.SetTexture("_MainTex", texture);
            }
            if (shader.name.StartsWith("Universal Render Pipeline/Particles")) SetupUrpParticle(mat, blend);
            else if (mat.HasProperty("_SrcBlend") && mat.HasProperty("_DstBlend")) SetBlend(mat, blend);
            mat.renderQueue = (int)RenderQueue.Transparent;
            EditorUtility.SetDirty(mat);
            return mat;
        }

        static void SetBlend(Material m, VfxBlend blend)
        {
            BlendMode src = BlendMode.SrcAlpha, dst = BlendMode.OneMinusSrcAlpha;
            if (blend == VfxBlend.Additive) dst = BlendMode.One;
            else if (blend == VfxBlend.Multiply) { src = BlendMode.DstColor; dst = BlendMode.Zero; }
            m.SetFloat("_SrcBlend", (float)src);
            m.SetFloat("_DstBlend", (float)dst);
            if (m.HasProperty("_ZWrite")) m.SetFloat("_ZWrite", 0);
        }

        static void SetupUrpParticle(Material m, VfxBlend blend)
        {
            m.SetFloat("_Surface", 1); // Transparent
            m.SetFloat("_Blend", blend == VfxBlend.Additive ? 2 : blend == VfxBlend.Multiply ? 3 : 0);
            SetBlend(m, blend);
            if (m.HasProperty("_SrcBlendAlpha"))
            {
                m.SetFloat("_SrcBlendAlpha", (float)BlendMode.One);
                m.SetFloat("_DstBlendAlpha", (float)BlendMode.OneMinusSrcAlpha);
            }
            m.SetOverrideTag("RenderType", "Transparent");
            m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
            if (blend == VfxBlend.Multiply) m.EnableKeyword("_ALPHAMODULATE_ON");
            else m.DisableKeyword("_ALPHAMODULATE_ON");
        }

        // ---------------------------------------------------------------- Hierarchy

        public static Transform Group(Transform parent, string name)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            return go.transform;
        }

        /// <summary>One-shot billboard layer: burst of 1 at t=0, no shape, no shadows, fixed seed. Configure further with the ParticleSystem API.</summary>
        public static ParticleSystem Particle(Transform parent, string name, Material material, float lifetime = 1f, float size = 1f, Color? color = null)
        {
            var go = new GameObject(name);
            go.transform.SetParent(parent, false);
            var ps = go.AddComponent<ParticleSystem>();
            ps.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);
            ps.useAutoRandomSeed = false;
            ps.randomSeed = (uint)Mathf.Abs(name.GetHashCode());

            var main = ps.main;
            main.duration = Mathf.Max(0.05f, lifetime);
            main.loop = false;
            main.playOnAwake = true;
            main.startLifetime = lifetime;
            main.startSpeed = 0f;
            main.startSize = size;
            main.startColor = color ?? Color.white;
            main.maxParticles = 50;
            main.simulationSpace = ParticleSystemSimulationSpace.Local;
            main.scalingMode = ParticleSystemScalingMode.Hierarchy;

            var emission = ps.emission;
            emission.rateOverTime = 0f;
            emission.SetBursts(new[] { new ParticleSystem.Burst(0f, 1) });
            var shape = ps.shape;
            shape.enabled = false;

            var r = go.GetComponent<ParticleSystemRenderer>();
            r.sharedMaterial = material;
            r.renderMode = ParticleSystemRenderMode.Billboard;
            r.shadowCastingMode = ShadowCastingMode.Off;
            r.receiveShadows = false;
            r.lightProbeUsage = LightProbeUsage.Off;
            r.reflectionProbeUsage = ReflectionProbeUsage.Off;
            return ps;
        }

        public static void Burst(ParticleSystem ps, int count, float time = 0f)
        {
            var emission = ps.emission;
            emission.SetBursts(new[] { new ParticleSystem.Burst(time, count) });
            var main = ps.main;
            main.maxParticles = Mathf.Max(count, 1);
        }

        // ---------------------------------------------------------------- Curves & gradients

        /// <summary>Curve from (time, value) pairs, e.g. AnimCurve(0, 0.5f, 1, 1.2f).</summary>
        public static AnimationCurve AnimCurve(params float[] timeValue)
        {
            var keys = new Keyframe[timeValue.Length / 2];
            for (int i = 0; i < keys.Length; i++) keys[i] = new Keyframe(timeValue[2 * i], timeValue[2 * i + 1]);
            return new AnimationCurve(keys);
        }

        public static ParticleSystem.MinMaxCurve Curve(params float[] timeValue) => new ParticleSystem.MinMaxCurve(1f, AnimCurve(timeValue));

        /// <summary>Colors spread evenly over 0..1 plus alpha (time, value) pairs. Max 8 keys each.</summary>
        public static Gradient Gradient(Color[] colors, params float[] alphaTimeValue)
        {
            var c = new GradientColorKey[colors.Length];
            for (int i = 0; i < colors.Length; i++) c[i] = new GradientColorKey(colors[i], colors.Length == 1 ? 0 : i / (float)(colors.Length - 1));
            var a = new GradientAlphaKey[Math.Max(1, alphaTimeValue.Length / 2)];
            if (alphaTimeValue.Length < 2) a[0] = new GradientAlphaKey(1, 0);
            for (int i = 0; i < alphaTimeValue.Length / 2; i++) a[i] = new GradientAlphaKey(alphaTimeValue[2 * i + 1], alphaTimeValue[2 * i]);
            var g = new Gradient();
            g.SetKeys(c, a);
            return g;
        }

        public static void SizeOverLifetime(ParticleSystem ps, params float[] timeValue)
        {
            var sol = ps.sizeOverLifetime;
            sol.enabled = true;
            sol.size = Curve(timeValue);
        }

        public static void AlphaOverLifetime(ParticleSystem ps, params float[] timeValue) => ColorOverLifetime(ps, new[] { Color.white }, timeValue);

        public static void ColorOverLifetime(ParticleSystem ps, Color[] colors, params float[] alphaTimeValue)
        {
            var col = ps.colorOverLifetime;
            col.enabled = true;
            col.color = new ParticleSystem.MinMaxGradient(Gradient(colors, alphaTimeValue));
        }

        /// <summary>Vertex streams for SH_VFX_Particle dissolve: Position, Color, UV, Custom1.x (packed into TEXCOORD0.xyz).</summary>
        public static void UseCustom1Stream(ParticleSystem ps)
        {
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.SetActiveVertexStreams(new List<ParticleSystemVertexStream>
            {
                ParticleSystemVertexStream.Position, ParticleSystemVertexStream.Color,
                ParticleSystemVertexStream.UV, ParticleSystemVertexStream.Custom1X
            });
        }

        // ---------------------------------------------------------------- Save, demo, preview, validate

        public static GameObject SavePrefab(GameObject root, string path)
        {
            try { return PrefabUtility.SaveAsPrefabAsset(root, path); }
            finally { Object.DestroyImmediate(root); }
        }

        /// <summary>
        /// Saves every direct child of root as its own component prefab (componentFolder/prefix + child name + ".prefab"),
        /// puts it back as a nested prefab instance (same local transform and order), then saves root as the effect prefab.
        /// Lets one layer be opened, tuned or reused on its own; rebuilding overwrites the component prefabs in place (GUIDs kept).
        /// </summary>
        public static GameObject SaveNested(GameObject root, string prefabPath, string componentFolder, string prefix)
        {
            try
            {
                Directory.CreateDirectory(componentFolder);
                AssetDatabase.Refresh();
                var children = new List<Transform>();
                foreach (Transform c in root.transform) children.Add(c);
                foreach (var c in children)
                {
                    Vector3 lp = c.localPosition, ls = c.localScale; Quaternion lr = c.localRotation; int index = c.GetSiblingIndex();
                    c.SetParent(null, false);   // save the layer as a prefab root with its own transform values
                    var asset = PrefabUtility.SaveAsPrefabAsset(c.gameObject, componentFolder + "/" + prefix + c.name + ".prefab");
                    Object.DestroyImmediate(c.gameObject);
                    var inst = (GameObject)PrefabUtility.InstantiatePrefab(asset, root.transform);
                    inst.transform.localPosition = lp; inst.transform.localRotation = lr; inst.transform.localScale = ls;
                    inst.transform.SetSiblingIndex(index);
                }
            }
            catch { Object.DestroyImmediate(root); throw; }
            return SavePrefab(root, prefabPath);
        }

        /// <summary>Asks to save modified scenes first (interactive) because building replaces the open scene. Returns false if cancelled.</summary>
        public static bool ConfirmSceneSwitch() => Application.isBatchMode || EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo();

        /// <summary>Validates, writes the preview sheet and demo scene, and reports to Docs/VFX/&lt;Effect&gt;/. Throws if validation fails.</summary>
        public static void Finish(GameObject prefab, string root, string effect, float[] previewTimes, Vector3? cameraPos = null, Vector3? lookAt = null)
        {
            string docs = Path.Combine("Docs/VFX", effect);
            Directory.CreateDirectory(docs);
            string scenePath = root + "/Scenes/" + effect + "_Demo.unity";

            var errors = Validate(root, prefab);
            CaptureSheet(prefab, previewTimes, Path.Combine(docs, "Preview_sheet.png"), 384, cameraPos, lookAt);
            DemoScene(prefab, scenePath, cameraPos, lookAt);
            AssetDatabase.SaveAssets();
            WriteReport(Path.Combine(docs, "BuildReport.txt"), effect, prefab, previewTimes, errors);

            if (errors.Count > 0) throw new InvalidOperationException(effect + " build has " + errors.Count + " error(s):\n" + string.Join("\n", errors));
            Debug.Log("[VfxKit] " + effect + " built OK. Preview: " + Path.Combine(docs, "Preview_sheet.png"));
        }

        public static List<string> Validate(string root, GameObject prefab)
        {
            var errors = new List<string>();
            foreach (var guid in AssetDatabase.FindAssets("t:Material", new[] { root }))
            {
                var path = AssetDatabase.GUIDToAssetPath(guid);
                var m = AssetDatabase.LoadAssetAtPath<Material>(path);
                if (m.shader == null || m.shader.name == "Hidden/InternalErrorShader") errors.Add("Broken shader on " + path);
                else if (ShaderUtil.ShaderHasError(m.shader)) errors.Add("Shader compile error: " + m.shader.name + " (" + path + ")");
                else if (IsAlphaBlend(m) && m.mainTexture != null && !HasUsableAlpha(m.mainTexture))
                    errors.Add("Alpha-blend material uses a texture without alpha (renders as a black square): " + path +
                               " -> import with alphaFromGray: true, or use VfxBlend.Additive");
            }
            foreach (var r in prefab.GetComponentsInChildren<Renderer>(true))
                if (r.sharedMaterials.Length == 0 || r.sharedMaterials.Any(x => x == null)) errors.Add("Missing material: " + PathOf(r.transform));
            foreach (var r in prefab.GetComponentsInChildren<ParticleSystemRenderer>(true))
                if (r.renderMode == ParticleSystemRenderMode.Mesh && r.mesh == null) errors.Add("Mesh render mode without mesh: " + PathOf(r.transform));
            return errors;
        }

        static bool IsAlphaBlend(Material m) =>
            m.HasProperty("_DstBlend") && (int)m.GetFloat("_DstBlend") == (int)BlendMode.OneMinusSrcAlpha && !m.IsKeywordEnabled("_GRAYSCALE_R")
            || m.shader.name == "Mobile/Particles/Alpha Blended";

        static bool HasUsableAlpha(Texture tex)
        {
            var importer = AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(tex)) as TextureImporter;
            if (importer == null) return true;
            return importer.alphaSource == TextureImporterAlphaSource.FromGrayScale
                || importer.alphaSource == TextureImporterAlphaSource.FromInput && importer.DoesSourceTextureHaveAlpha();
        }

        public static void CaptureSheet(GameObject prefab, float[] times, string outPng, int size = 384, Vector3? cameraPos = null, Vector3? lookAt = null)
        {
            EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
            var cam = new GameObject("CaptureCamera").AddComponent<Camera>();
            cam.transform.position = cameraPos ?? new Vector3(0, 2.5f, -6);
            cam.transform.LookAt(lookAt ?? new Vector3(0, 0.5f, 0));
            cam.clearFlags = CameraClearFlags.SolidColor;
            cam.backgroundColor = new Color(0.12f, 0.12f, 0.14f, 1);
            cam.fieldOfView = 50;
            var light = new GameObject("Light").AddComponent<Light>();
            light.type = LightType.Directional;
            light.transform.rotation = Quaternion.Euler(50, -30, 0);

            var inst = (GameObject)PrefabUtility.InstantiatePrefab(prefab);
            var roots = inst.GetComponentsInChildren<ParticleSystem>(true)
                .Where(p => p.transform.parent == null || p.transform.parent.GetComponentInParent<ParticleSystem>() == null)
                .ToArray();

            var rt = new RenderTexture(size, size, 24, RenderTextureFormat.ARGB32);
            var frame = new Texture2D(size, size, TextureFormat.RGB24, false);
            var sheet = new Texture2D(size * times.Length, size, TextureFormat.RGB24, false);
            cam.targetTexture = rt;
            try
            {
                for (int i = 0; i < times.Length; i++)
                {
                    foreach (var p in roots) p.Simulate(times[i], true, true, true);
                    cam.Render();
                    RenderTexture.active = rt;
                    frame.ReadPixels(new Rect(0, 0, size, size), 0, 0);
                    frame.Apply();
                    sheet.SetPixels(i * size, 0, size, size, frame.GetPixels());
                }
                sheet.Apply();
                Directory.CreateDirectory(Path.GetDirectoryName(outPng));
                File.WriteAllBytes(outPng, sheet.EncodeToPNG());
            }
            finally
            {
                RenderTexture.active = null;
                cam.targetTexture = null;
                rt.Release();
                Object.DestroyImmediate(rt);
                Object.DestroyImmediate(frame);
                Object.DestroyImmediate(sheet);
            }
        }

        public static void DemoScene(GameObject prefab, string scenePath, Vector3? cameraPos = null, Vector3? lookAt = null, float replayInterval = 3f)
        {
            var scene = EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects, NewSceneMode.Single);
            var cam = Camera.main;
            cam.transform.position = cameraPos ?? new Vector3(0, 2.5f, -6);
            cam.transform.LookAt(lookAt ?? new Vector3(0, 0.5f, 0));
            cam.clearFlags = CameraClearFlags.SolidColor;
            cam.backgroundColor = new Color(0.12f, 0.12f, 0.14f, 1);

            var inst = (GameObject)PrefabUtility.InstantiatePrefab(prefab, scene);
            var replay = new GameObject("VfxDemoReplay").AddComponent<VfxDemoReplay>();
            replay.target = inst;
            replay.interval = replayInterval;

            Directory.CreateDirectory(Path.GetDirectoryName(scenePath));
            EditorSceneManager.SaveScene(scene, scenePath);
        }

        static void WriteReport(string path, string effect, GameObject prefab, float[] times, List<string> errors)
        {
            var sb = new StringBuilder();
            sb.AppendLine("Effect: " + effect + "   Kit: " + Version + "   Unity: " + Application.unityVersion + "   Pipeline: " + (IsURP ? "URP" : "Built-in"));
            sb.AppendLine("Built: " + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));
            sb.AppendLine("Preview times (s): " + string.Join(", ", times.Select(t => t.ToString("0.###"))));
            sb.AppendLine();
            int total = 0;
            sb.AppendLine("Layers:");
            foreach (var ps in prefab.GetComponentsInChildren<ParticleSystem>(true))
            {
                var r = ps.GetComponent<ParticleSystemRenderer>();
                var m = r.sharedMaterial;
                total += ps.main.maxParticles;
                sb.AppendLine("  " + PathOf(ps.transform) + "  max=" + ps.main.maxParticles + "  life=" + ps.main.startLifetime.constantMax.ToString("0.##") +
                              "  mode=" + r.renderMode + "  mat=" + (m ? m.name + " (" + m.shader.name + ")" : "NONE"));
            }
            sb.AppendLine("Total maxParticles: " + total);
            sb.AppendLine();
            sb.AppendLine(errors.Count == 0 ? "Errors: none" : "Errors:\n  " + string.Join("\n  ", errors));
            File.WriteAllText(path, sb.ToString());
        }

        static string PathOf(Transform t) => t.parent == null ? t.name : PathOf(t.parent) + "/" + t.name;

        /// <summary>Entry point for -executeMethod: runs build and exits with 0 on success, 1 on failure.</summary>
        public static void RunBatch(Action build)
        {
            try { build(); EditorApplication.Exit(0); }
            catch (Exception e) { Debug.LogException(e); EditorApplication.Exit(1); }
        }
    }
}
#endif
